175	// text: the escape escEmoji decodes to the emoji, while
176	// escLiteralBackslashID decodes to twelve literal characters starting with
177	// a backslash. The two are different batches and must never be merged.
178	func TestImportLiteralBackslashIDIsNotThePairEscape(t *testing.T) {
