238		}
239		if results[0].Batch.Batch != "B-"+fffd || results[1].Batch.Batch != "C-"+fffd {
240			t.Fatalf("decoded ids wrong: %+v", results)
241		}
242		if len(reg.Batches) != 2 || reg.Batches[0].Batch != "B-"+fffd || reg.Batches[1].Batch != "C-"+fffd {
243			t.Fatalf("registry must hold exactly the two genuine-FFFD ids: %+v", reg.Batches)
244		}
