247	// TestParseManifestRejectsLoneSurrogateShapes covers every malformed
248	// surrogate shape: a lone high or low surrogate, a reversed pair, a high
249	// surrogate followed by a plain character, and two high surrogates. Each
250	// fails the manifest at the record's 1-based position naming the batch
251	// field — never substituted with U+FFFD and registered, and never cited
252	// back as an undecodable id — even when a legal record precedes it.
253	func TestParseManifestRejectsLoneSurrogateShapes(t *testing.T) {
254		cases := map[string]string{
255			"lone high surrogate":              "B" + bs + "ud83d",
256			"lone low surrogate":               "B" + bs + "ude00",
257			"reversed surrogate pair":          "B" + bs + "ude00" + bs + "ud83d",
258			"high surrogate then plain letter": "B" + bs + "ud83d" + "X",
259			"two high surrogates":              "B" + bs + "ud83d" + bs + "ud83d",
260		}
261		for name, id := range cases {
262			t.Run(name, func(t *testing.T) {
263				manifest := `[
264					{"batch":"OK-1","product":"P","quantity":1,"unit":"kg"},
265					{"batch":"` + id + `","product":"P","quantity":2,"unit":"kg"}
266				]`
267				_, err := ParseManifest([]byte(manifest))
268				var re *ManifestRecordError
269				if !errors.As(err, &re) {
270					t.Fatalf("got %v, want ManifestRecordError", err)
271				}
272				if re.Position != 2 {
273					t.Errorf("position = %d, want 2", re.Position)
274				}
275				if re.Batch != "" {
276					t.Errorf("an undecodable id must not be cited, got %q", re.Batch)
277				}
278				if !strings.Contains(re.Reason, `"batch"`) {
279					t.Errorf("reason must name the batch field: %q", re.Reason)
280				}
281				if strings.Contains(err.Error(), string(rune(0xfffd))) {
282					t.Errorf("error must not substitute U+FFFD for the bad escape: %v", err)
283				}
284			})
285		}
286	}
