1	package main
2	
3	import (
4		"bytes"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	)
10	
11	// End-to-end regression for a --registry path that the user spells as a
12	// DIRECTORY location rather than a file: it ends in one or more separators
13	// ("store/new.json/"), or its final component is "." or ".."
14	// ("store/new/.", "store/new/.."). Both commands must reject such a path
15	// instead of reporting "created": a non-zero exit code, stderr carrying the
16	// exact user-supplied registry path and stating that the registry target
17	// must be a file while this path denotes a directory, and empty stdout with
18	// no "created", "duplicate" or import "results" payload anywhere.
19	//
20	// The rejection must hold whether the location does not exist yet, already is
21	// a directory, or has a regular file directly beneath the spelled name; it
22	// must create no missing parent directory, no plain file at the name left
23	// after stripping the trailing marker, and no save temporary file. Relative
24	// and absolute spellings behave alike. A normal file path — one without a
25	// ".json" suffix included — keeps registering successfully.
26	
27	// cliDirShapes returns the directory-marker shapes over the store directory
28	// plus the stripped plain-file name a stripping save would wrongly create and
29	// the directory that would first have to be brought into existence. The
30	// paths are raw-joined so the trailing separator and final "."/".." survive.
31	func cliDirShapes(store string) []struct {
32		name       string
33		path       string
34		stripped   string
35		missingDir string
36	} {
37		sep := string(os.PathSeparator)
38		return []struct {
39			name       string
40			path       string
41			stripped   string
42			missingDir string
43		}{
44			{"trailing slash", store + sep + "new.json" + sep, filepath.Join(store, "new.json"), ""},
45			{"two trailing slashes", store + sep + "new.json" + sep + sep, filepath.Join(store, "new.json"), ""},
46			{"final dot", store + sep + "new" + sep + ".", filepath.Join(store, "new"), filepath.Join(store, "new")},
47			{"final dot-dot", store + sep + "new" + sep + "..", filepath.Join(store, "new"), filepath.Join(store, "new")},
48		}
49	}
50	
51	// assertDirectoryChildFailure checks the process contract shared by both
52	// commands: exit code 1, empty stdout, and stderr carrying the "govflow:"
53	// prefix, the exact user registry path and the file-vs-directory reason — with
54	// no success token anywhere in either stream. The wrapped child does not add a
55	// per-command prefix, so none is required.
56	func assertDirectoryChildFailure(t *testing.T, code int, stdout, stderr []byte, userPath string) {
57		t.Helper()
58		if code != 1 {
59			t.Fatalf("exit code = %d, want 1; stderr:\n%s", code, stderr)
60		}
61		if len(bytes.TrimSpace(stdout)) != 0 {
62			t.Fatalf("stdout must stay empty for the directory path, got %q", stdout)
63		}
64		msg := string(stderr)
65		for _, want := range []string{
66			"govflow:",
67			userPath,
68			"must be a file",
69			"directory",
70		} {
71			if !strings.Contains(msg, want) {
72				t.Errorf("stderr must contain %q:\n%s", want, msg)
73			}
74		}
75		for _, banned := range []string{`"status":"created"`, `"status":"duplicate"`, `"results"`} {
76			if strings.Contains(msg, banned) || bytes.Contains(stdout, []byte(banned)) {
77				t.Errorf("no success payload %q may appear: stdout=%q stderr=%s", banned, stdout, msg)
78			}
79		}
80	}
81	
82	// assertStrippedNameNotCreated verifies nothing appeared at the stripped file
83	// name or at the directory the marker descended into.
84	func assertStrippedNameNotCreated(t *testing.T, stripped, missingDir string) {
85		t.Helper()
86		if _, err := os.Lstat(stripped); !os.IsNotExist(err) {
87			t.Fatalf("the rejected command must not create the stripped name %q, stat err=%v", stripped, err)
88		}
89		if missingDir != "" {
90			if _, err := os.Lstat(missingDir); !os.IsNotExist(err) {
91				t.Fatalf("the rejected command must not create the missing directory %q, stat err=%v", missingDir, err)
92			}
93		}
94	}
95	
96	// batch-register of a legal NEW batch against every directory-marker shape,
97	// over a location that does not exist, fails the process contract and creates
98	// neither the stripped plain file nor the missing parent directory.
99	func TestBatchRegisterCLIDirectorySpellingMissingRejected(t *testing.T) {
100		for _, tc := range []struct {
101			name string
102			rel  bool
103		}{
104			{"absolute", false},
105			{"relative", true},
106		} {
107			t.Run(tc.name, func(t *testing.T) {
108				root := t.TempDir()
109				storeAbs := filepath.Join(root, "store")
110				if err := os.MkdirAll(storeAbs, 0o755); err != nil {
111					t.Fatal(err)
112				}
113				if tc.rel {
114					t.Chdir(root)
115				}
116				store := storeAbs
117				if tc.rel {
118					store = "store"
119				}
120				for _, shape := range cliDirShapes(store) {
121					t.Run(shape.name, func(t *testing.T) {
122						var code int
123						var stdout, stderr []byte
124						if tc.rel {
125							var buf bytes.Buffer
126							err := runBatchRegister([]string{
127								"--registry", shape.path,
128								"--batch", "NEW", "--product", "P-9", "--quantity", "5", "--unit", "box",
129							}, &buf)
130							if err == nil {
131								t.Fatal("registering against a directory-denoting relative path must fail")
132							}
133							assertDirectoryInProcessFailure(t, err, buf.Bytes(), shape.path, "batch-register")
134							stdout = buf.Bytes()
135						} else {
136							code, stdout, stderr = runRegisterChild(t, shape.path, faultNone, "", false)
137							assertDirectoryChildFailure(t, code, stdout, stderr, shape.path)
138						}
139						if len(bytes.TrimSpace(stdout)) != 0 {
140							t.Fatalf("stdout must stay empty, got %q", stdout)
141						}
142						stripped := shape.stripped
143						missing := shape.missingDir
144						if tc.rel && missing != "" {
145							missing = filepath.Join(root, missing)
146						}
147						assertStrippedNameNotCreated(t, stripped, missing)
148						assertNoSaveLeftovers(t, root)
149					})
150				}
151			})
152		}
153	}
154	
155	// assertDirectoryInProcessFailure is the in-process counterpart of
156	// assertDirectoryChildFailure: an error naming the exact path and the
157	// file-vs-directory reason, with nothing written to stdout.
158	func assertDirectoryInProcessFailure(t *testing.T, err error, stdout []byte, userPath, command string) {
159		t.Helper()
160		if err == nil {
161			t.Fatal("the directory-denoting path must be rejected")
162		}
163		if len(stdout) != 0 {
164			t.Fatalf("stdout must stay empty, got %q", stdout)
165		}
166		msg := err.Error()
167		for _, want := range []string{userPath, "must be a file", "directory"} {
168			if !strings.Contains(msg, want) {
169				t.Errorf("error %q must contain %q (command %s)", msg, want, command)
170			}
171		}
172	}
173	
174	// When the location already IS a directory, both commands reject it and the
175	// directory survives; when a plain file sits directly beneath the spelled
176	// name, that file's bytes and pinned modification time are untouched.
177	func TestBatchCommandsCLIDirectorySpellingOverExistingFsObjects(t *testing.T) {
178		const oldJSON = `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`
179	
180		t.Run("register over existing directory", func(t *testing.T) {
181			root := t.TempDir()
182			store := filepath.Join(root, "store")
183			dir := filepath.Join(store, "dir")
184			if err := os.MkdirAll(dir, 0o755); err != nil {
185				t.Fatal(err)
186			}
187			for _, userPath := range []string{
188				dir + string(os.PathSeparator),
189				dir + string(os.PathSeparator) + ".",
190				dir + string(os.PathSeparator) + "..",
191			} {
192				code, stdout, stderr := runRegisterChild(t, userPath, faultNone, "", false)
193				assertDirectoryChildFailure(t, code, stdout, stderr, userPath)
194				if info, err := os.Stat(dir); err != nil || !info.IsDir() {
195					t.Fatalf("the existing directory must survive: info=%+v err=%v", info, err)
196				}
197				assertNoSaveLeftovers(t, root)
198			}
199		})
200	
201		t.Run("import over existing directory", func(t *testing.T) {
202			root := t.TempDir()
203			store := filepath.Join(root, "store")
204			dir := filepath.Join(store, "dir")
205			if err := os.MkdirAll(dir, 0o755); err != nil {
206				t.Fatal(err)
207			}
208			manifest := filepath.Join(root, "manifest.json")
209			writeFile(t, manifest, `[{"batch":"NEW","product":"P-9","quantity":5,"unit":"box"}]`)
210			userPath := dir + string(os.PathSeparator)
211	
212			code, stdout, stderr := runImportChild(t, userPath, manifest, faultNone, "", false)
213			assertDirectoryChildFailure(t, code, stdout, stderr, userPath)
214			assertNoSaveLeftovers(t, root, "manifest.json")
215		})
216	
217		t.Run("register over regular file beneath the name", func(t *testing.T) {
218			for _, shape := range []struct {
219				name string
220				file string
221				path string
222			}{
223				{"trailing slash", "new.json", "new.json" + string(os.PathSeparator)},
224				{"final dot", "new", "new" + string(os.PathSeparator) + "."},
225				{"final dot-dot", "new", "new" + string(os.PathSeparator) + ".."},
226			} {
227				t.Run(shape.name, func(t *testing.T) {
228					root := t.TempDir()
229					store := filepath.Join(root, "store")
230					if err := os.MkdirAll(store, 0o755); err != nil {
231						t.Fatal(err)
232					}
233					existing := filepath.Join(store, shape.file)
234					writeFile(t, existing, oldJSON)
235					content, pinned := pinRegistry(t, existing)
236					userPath := store + string(os.PathSeparator) + shape.path
237	
238					code, stdout, stderr := runRegisterChild(t, userPath, faultNone, "", true)
239					assertDirectoryChildFailure(t, code, stdout, stderr, userPath)
240					assertRegistryUntouched(t, existing, content, pinned)
241					if got := readStoredBatches(t, existing); len(got) != 1 || got[0].Batch != "OLD" {
242						t.Fatalf("the file beneath the name must keep exactly OLD, got %+v", got)
243					}
244					assertNoSaveLeftovers(t, root, shape.file)
245				})
246			}
247		})
248	
249		t.Run("import all-duplicate manifest over directory still rejected", func(t *testing.T) {
250			// Even when every manifest row would merely confirm a duplicate, a
251			// directory-denoting registry path must fail before stdout can carry
252			// a single "duplicate" result.
253			root := t.TempDir()
254			store := filepath.Join(root, "store")
255			if err := os.MkdirAll(filepath.Join(store, "dir"), 0o755); err != nil {
256				t.Fatal(err)
257			}
258			registry := filepath.Join(store, "batches.json")
259			writeFile(t, registry, oldJSON)
260			manifest := filepath.Join(root, "manifest.json")
261			writeFile(t, manifest, `[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]`)
262			userPath := filepath.Join(store, "dir") + string(os.PathSeparator)
263	
264			code, stdout, stderr := runImportChild(t, userPath, manifest, faultNone, "", false)
265			assertDirectoryChildFailure(t, code, stdout, stderr, userPath)
266			if got := readStoredBatches(t, registry); len(got) != 1 || got[0].Batch != "OLD" {
267				t.Fatalf("the real registry must keep exactly OLD, got %+v", got)
268			}
269			assertNoSaveLeftovers(t, root, "batches.json", "manifest.json")
270		})
271	}
272	
273	// Relative in-process spellings of the existing-directory and
274	// file-beneath shapes fail for both commands with the same contract.
275	func TestBatchCommandsCLIDirectorySpellingRelativeRejected(t *testing.T) {
276		root := t.TempDir()
277		store := filepath.Join(root, "store")
278		if err := os.MkdirAll(filepath.Join(store, "dir"), 0o755); err != nil {
279			t.Fatal(err)
280		}
281		existing := filepath.Join(store, "new.json")
282		writeFile(t, existing, `{"version":1,"batches":[{"batch":"OLD","product":"P-1","quantity":10,"unit":"kg"}]}`)
283		content, pinned := pinRegistry(t, existing)
284		manifest := filepath.Join(root, "manifest.json")
285		manifestJSON := `[{"batch":"NEW","product":"P-9","quantity":5,"unit":"box"}]`
286		writeFile(t, manifest, manifestJSON)
287		t.Chdir(root)
288	
289		paths := []string{
290			filepath.Join("store", "dir") + string(os.PathSeparator),
291			filepath.Join("store", "new.json") + string(os.PathSeparator),
292			"store" + string(os.PathSeparator) + "new" + string(os.PathSeparator) + ".",
293		}
294		for _, userPath := range paths {
295			t.Run("register/"+strings.ReplaceAll(userPath, string(os.PathSeparator), "_"), func(t *testing.T) {
296				var stdout bytes.Buffer
297				err := runBatchRegister([]string{
298					"--registry", userPath,
299					"--batch", "NEW", "--product", "P-9", "--quantity", "5", "--unit", "box",
300				}, &stdout)
301				assertDirectoryInProcessFailure(t, err, stdout.Bytes(), userPath, "batch-register")
302				assertRegistryUntouched(t, existing, content, pinned)
303			})
304			t.Run("import/"+strings.ReplaceAll(userPath, string(os.PathSeparator), "_"), func(t *testing.T) {
305				var stdout bytes.Buffer
306				err := runBatchImport([]string{"--registry", userPath, "--input", manifest}, &stdout)
307				assertDirectoryInProcessFailure(t, err, stdout.Bytes(), userPath, "batch-import")
308				assertRegistryUntouched(t, existing, content, pinned)
309				if after, _ := os.ReadFile(manifest); string(after) != manifestJSON {
310					t.Fatal("the read-only manifest was modified")
311				}
312			})
313		}
314	}
315	
316	// Preserved normal behavior: a file path without a ".json" suffix, whose
317	// parent does not exist, still creates the directory and the registry and
318	// reports created — the new rule is specific to directory-marker spellings.
319	func TestBatchRegisterCLINormalFileWithoutSuffixStillCreated(t *testing.T) {
320		root := t.TempDir()
321		registry := filepath.Join(root, "store", "new", "registry-data")
322	
323		stdout, err := registerCLI(t, registry, "NEW", "P-9", "5", "box")
324		if err != nil {
325			t.Fatalf("a normal file path without a .json suffix must register: %v", err)
326		}
327		if got := decodeRegisterResult(t, stdout); got.Status != "created" || got.Batch != "NEW" {
328			t.Fatalf("unexpected result: %+v", got)
329		}
330		if got := readStoredBatches(t, registry); len(got) != 1 || got[0].Batch != "NEW" {
331			t.Fatalf("the new registry must hold NEW, got %+v", got)
332		}
333		assertNoSaveLeftovers(t, filepath.Join(root, "store"), "registry-data")
334	}
