212				manifestPath := filepath.Join(root, "in.json")
213				writeFile(t, manifestPath, `[{"batch":"B1","product":"P","quantity":1,"unit":"kg"}]`)
214	
215				var stdout bytes.Buffer
216				var err error
217				if command == "batch-register" {
218					err = runBatchRegister([]string{
219						"--registry", userPath,
220						"--batch", "B1", "--product", "P", "--quantity", "1", "--unit", "kg",
221					}, &stdout)
222				} else {
223					err = runBatchImport([]string{"--registry", userPath, "--input", manifestPath}, &stdout)
224				}
225				if err != nil {
226					t.Fatalf("a first registration through a valid directory link must succeed: %v", err)
227				}
228				if stdout.Len() == 0 {
229					t.Fatal("stdout must carry the normal success result")
230				}
231				if got := batchIDs(t, realRegistry); len(got) != 1 || got[0] != "B1" {
232					t.Fatalf("the registry must be created in the real directory with B1, got %v", got)
233				}
234				if got := batchIDs(t, userPath); len(got) != 1 || got[0] != "B1" {
235					t.Fatalf("the new registry must read back through the link, got %v", got)
236				}
237				assertStillSymlink(t, aliasPath, linkTarget)
238			})
239		}
240	}
241

